window.ScripturaLexicons.BDAG_PART_0031 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anapempo-bdag\" data-source=\"BDAG\" data-search=\"ἀναπέμπω anapempo enviar para cima enviar autoridade remeter devolver enviar de volta Lucas Atos Filemom BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναπέμπω</td><td>Verbo</td><td>enviar para cima; remeter; enviar de volta</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anapese-bdag\" data-source=\"BDAG\" data-search=\"ἀνάπεσε anapese εῖν forma verbal veja ἀναπίπτω reclinar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάπεσε</td><td>Remissão</td><td>veja ἀναπίπτω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anapetannymi-bdag\" data-source=\"BDAG\" data-search=\"ἀναπετάννυμι anapetannymi abrir escancarar abrir-se portas portões BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναπετάννυμι</td><td>Verbo</td><td>abrir-se; escancarar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anapedao-bdag\" data-source=\"BDAG\" data-search=\"ἀναπηδάω anapedao saltar levantar-se ficar de pé Marcos 10.50 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναπηδάω</td><td>Verbo</td><td>saltar; levantar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anaperos-bdag\" data-source=\"BDAG\" data-search=\"ἀνάπηρος anaperos aleijado deficiente físico ἀνάπειρος Lucas 14.13 14.21 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάπηρος</td><td>Adjetivo substantivado</td><td>aleijado; pessoa com deficiência física</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anapipto-bdag\" data-source=\"BDAG\" data-search=\"ἀναπίπτω anapipto reclinar deitar mesa refeição inclinar-se recostar-se Lucas João Marcos Mateus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναπίπτω</td><td>Verbo</td><td>reclinar-se; recostar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anaplasso-bdag\" data-source=\"BDAG\" data-search=\"ἀναπλάσσω anaplasso formar novamente remodelar refazer transformação espiritual oleiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναπλάσσω</td><td>Verbo</td><td>formar de novo; remodelar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anapleroo-bdag\" data-source=\"BDAG\" data-search=\"ἀναπληρόω anapleroo completar cumprir suprir falta preencher ocupar lugar pecados profecia lei Cristo 1 Coríntios Filipenses Gálatas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναπληρόω</td><td>Verbo</td><td>completar; cumprir; suprir; ocupar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anapneo-bdag\" data-source=\"BDAG\" data-search=\"ἀναπνέω anapneo respirar recobrar fôlego reanimar reviver Artemila BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναπνέω</td><td>Verbo</td><td>respirar; reanimar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anapologetos-bdag\" data-source=\"BDAG\" data-search=\"ἀναπολόγητος anapologetos sem desculpa indesculpável inexcusável Romanos 1.20 2.1 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναπολόγητος</td><td>Adjetivo</td><td>sem desculpa; indesculpável</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anaprasso-bdag\" data-source=\"BDAG\" data-search=\"ἀναπράσσω anaprasso exigir cobrar pagamento termo comercial Lucas 19.23 variante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναπράσσω</td><td>Verbo</td><td>exigir; cobrar pagamento</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anaptysso-bdag\" data-source=\"BDAG\" data-search=\"ἀναπτύσσω anaptysso desenrolar rolo livro Lucas 4.17 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναπτύσσω</td><td>Verbo</td><td>desenrolar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anapto-bdag\" data-source=\"BDAG\" data-search=\"ἀνάπτω anapto acender atear fogo incendiar queimar Tiago Lucas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάπτω</td><td>Verbo</td><td>acender; atear fogo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anarithmetos-bdag\" data-source=\"BDAG\" data-search=\"ἀναρίθμητος anarithmetos inumerável incontável areia mar Hebreus 11.12 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναρίθμητος</td><td>Adjetivo</td><td>inumerável; incontável</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anarpazo-bdag\" data-source=\"BDAG\" data-search=\"ἀναρπάζω anarpazo levantar erguer carregar para cima Evangelho Tiago BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναρπάζω</td><td>Verbo</td><td>levantar; carregar para cima</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anaseio-bdag\" data-source=\"BDAG\" data-search=\"ἀνασείω anaseio agitar perturbar incitar multidão povo Marcos Lucas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνασείω</td><td>Verbo</td><td>agitar; perturbar; incitar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anaskapto-bdag\" data-source=\"BDAG\" data-search=\"ἀνασκάπτω anaskapto escavar arrasar destruir Atos 15.16 variante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνασκάπτω</td><td>Verbo</td><td>escavar; arrasar; destruir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anaskeuazo-bdag\" data-source=\"BDAG\" data-search=\"ἀνασκευάζω anaskeuazo desmontar transtornar perturbar inquietar almas Atos 15.24 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνασκευάζω</td><td>Verbo</td><td>desmontar; perturbar; transtornar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anaspa0-bdag\" data-source=\"BDAG\" data-search=\"ἀνασπάω anaspao puxar para cima erguer lençol céu Lucas Atos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνασπάω</td><td>Verbo</td><td>puxar para cima; erguer</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anasta-bdag\" data-source=\"BDAG\" data-search=\"ἀνάστα anasta veja ἀνίστημι forma verbal levanta-te BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάστα</td><td>Remissão</td><td>veja ἀνίστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anastasis-bdag\" data-source=\"BDAG\" data-search=\"ἀνάστασις anastasis levantamento elevação ressurreição mortos ressurreição Jesus ressurreição futura vida julgamento divindade Ressurreição Atos Lucas João Romanos Coríntios Hebreus Apocalipse BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάστασις</td><td>Substantivo feminino</td><td>levantamento; ressurreição</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anastatoo-bdag\" data-source=\"BDAG\" data-search=\"ἀναστατόω anastatoo perturbar transtornar desestabilizar revolta mundo igreja Atos Gálatas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναστατόω</td><td>Verbo</td><td>perturbar; transtornar; desestabilizar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anastauroo-bdag\" data-source=\"BDAG\" data-search=\"ἀνασταυρόω anastauroo crucificar crucificar novamente Hebreus 6.6 apostasia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνασταυρόω</td><td>Verbo</td><td>crucificar; crucificar novamente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anastenazo-bdag\" data-source=\"BDAG\" data-search=\"ἀναστενάζω anastenazo suspirar profundamente gemer espírito Marcos 8.12 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναστενάζω</td><td>Verbo</td><td>suspirar profundamente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anastethi-bdag\" data-source=\"BDAG\" data-search=\"ἀνάστηθι anastethi veja ἀνίστημι levantar erguer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάστηθι</td><td>Remissão</td><td>veja ἀνίστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anastrepho-bdag\" data-source=\"BDAG\" data-search=\"ἀναστρέφω anastrepho virar derrubar permanecer viver comportar conduzir associar retornar voltar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναστρέφω</td><td>Verbo</td><td>derrubar; viver; comportar-se; associar-se; retornar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anastrophe-bdag\" data-source=\"BDAG\" data-search=\"ἀναστροφή anastrophe conduta comportamento modo vida viver estilo de vida Gálatas Efésios Pedro Tiago BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναστροφή</td><td>Substantivo feminino</td><td>modo de vida; conduta; comportamento</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anasozo-bdag\" data-source=\"BDAG\" data-search=\"ἀνασῴζω anasozo resgatar salvar Hebreus 10.14 P46 variante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνασῴζω</td><td>Verbo</td><td>resgatar; salvar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anatassomai-bdag\" data-source=\"BDAG\" data-search=\"ἀνατάσσομαι anatassomai organizar ordenar compilar compor narrativa Lucas 1.1 material tradicional sequência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνατάσσομαι</td><td>Verbo</td><td>organizar; compor; compilar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anatethrammenos-bdag\" data-source=\"BDAG\" data-search=\"ἀνατεθραμμένος anatethrammenos veja ἀνατρέφω criar educar nutrir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνατεθραμμένος</td><td>Remissão</td><td>veja ἀνατρέφω</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-anapempo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναπέμπω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anapémpō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀναπέμψω</span>; 1º aoristo <span class=\"greek\">ἀνέπεμψα</span>. Veja <span class=\"greek\">πέμπω</span>; Píndaro, Ésquilo e posteriores; inscrições, papiros; TestJob 48.3; Fílon, Josefo, Justino; Melito, <em>P.</em> 91, 687.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Enviar para cima, de uma posição inferior para outra superior</strong> — Ps.-Aristóteles, <em>Mirabilia</em> 114, <span class=\"greek\">φλόγα πυρός</span> —; em direção ao céu — Bias em Diógenes Laércio 1.88, <span class=\"greek\">εἰς θεοὺς ἀνάπεμπε</span> —: <span class=\"greek\">τὸ ἀμήν</span>, <strong>o amém</strong>, MPol 15.1; compare Justino, <em>A I</em> 65.3, <span class=\"greek\">δόξαν</span>; 67.5, <span class=\"greek\">εὐχαριστίας</span>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Enviar a alguém em posição de autoridade, remeter — enviar para cima — a uma autoridade superior</strong> — Plutarco, <em>Marius</em> 415 [17, 3]; Josefo, <em>Bell.</em> 2.571; OGI 329, 51; PHib 1, 57 [séc. III a.C.]; PTebt 7, 7; daí, termo técnico para remeter à pessoa ou repartição governamental competente, Josefo, <em>Ant.</em> 4.218; Nägeli 34. <span class=\"greek\">τινὰ πρός τινα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.7</a>; HHoehner, Festschrift de C. F. D. Moule, 1970, 84–90, sobre Antipas; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.21</a>. Para isso, <span class=\"greek\">τινά τινι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.1</a> v.l.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Enviar de volta a um lugar anterior</strong> — Plutarco, <em>Sol.</em> 80 [4, 6]; PParis 13, 22 [157 a.C.]; POxy 1032, 50 [162 d.C.]; Melito, <em>P.</em> 91, 687 —: <span class=\"greek\">τινά τινι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.11</a>, v.l. <span class=\"greek\">πέμπω</span> em P75 e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 12</a>; <span class=\"greek\">τινὰ πρός τινα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.15</a>; 1 Cl 65.1. — M-M. Spicq.</p>\n</section></article><article id=\"entry-anapese-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάπεσε, εῖν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anápese⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀναπίπτω</span>.</p>\n</section></article><article id=\"entry-anapetannymi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναπετάννυμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anapetánnumi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Particípio do 1º aoristo <span class=\"greek\">ἀναπετάσας</span>, Jó 39.26; 1º aoristo passivo <span class=\"greek\">ἀνεπετάσθην</span>. De <span class=\"greek\">πετάννυμι</span>, “estender, abrir”; Homero e posteriores; PMich 425, 16 [198 d.C.]; Jó 39.26, “abrir as asas”; Josefo. Em nossa literatura, passivo com sentido ativo: <strong>abrir-se de repente, escancarar-se, abrir-se</strong>, a respeito de portas vigiadas: <span class=\"greek\">[οἱ κεκλισμένοι πυ]λῶνες ἐν [ὀνό]ματι θεοῦ ἀνεπετ[άσθησαν]</span>, <strong>então os portões [que haviam sido fechados] abriram-se em nome de Deus</strong>, AcPl Ha 3, 24. — DELG s.v. <span class=\"greek\">πετάννυμι</span>.</p>\n</section></article><article id=\"entry-anapedao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναπηδάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anapēdáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἀνεπήδησα</span>. Veja <span class=\"greek\">πηδάω</span>; Homero e posteriores; PHib, LXX; En 89.48; TestSol 9.3; Josefo, <em>Vi.</em> 265. <strong>Saltar para cima</strong>; também, com força enfraquecida, <strong>levantar-se, ficar de pé</strong> — Epicteto 3.4.4; Tb 2.4; 7.6; PGM 1, 93; Josefo, <em>Ant.</em> 8.360 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.50</a>.</p>\n</section></article><article id=\"entry-anaperos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάπηρος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anápēros⟧</span><span class=\"separator\">·</span><span>adjetivo substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνάπειρος</span>, <span class=\"greek\">πηρός</span>; forma ática, como em Sófocles e outros; TestAbr A 1 p. 77, 7 [Stone p. 2]; Josefo, <em>Ant.</em> 7.61. Substantivado: <strong>uma pessoa aleijada, uma pessoa com deficiência física</strong>, com <span class=\"greek\">πτωχός, χωλός, τυφλός</span> — Platão, <em>Crit.</em> 53a, <span class=\"greek\">χωλοὶ καὶ τυφλοὶ καὶ ἄλλοι ἀνάπηροι</span>; Eliano, <em>VH</em> 11.9 p. 115, 23; Diógenes Laércio 6.33 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.13</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">14.21</a> v.l.</p>\n</section></article><article id=\"entry-anapipto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναπίπτω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anapíptō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro 3ª sg. <span class=\"greek\">ἀναπεσεῖται</span>, Sir 25.18; 2º aoristo <span class=\"greek\">ἀνέπεσον</span> e a forma posterior <span class=\"greek\">ἀνέπεσα</span>; veja W-S. §13, 13; B-D-F §81, 3; Mlt-H. 208. Veja <span class=\"greek\">πίπτω</span>; trágicos e outros; UPZ 78, 4 [séc. II a.C.], LXX; TestAbr A; Josefo, <em>Ant.</em> 8.256.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Reclinar-se num leito para comer, deitar-se, reclinar-se</strong> — Diodoro Sículo 4.59.5, na história de Procusto, <span class=\"greek\">ἐπί τινος κλίνης</span>; Syntipas 48, 29, <span class=\"greek\">ἀ. ἐπὶ τ. κλίνης</span> —, especialmente numa refeição — Alexis Com. 293 [em Ateneu 1.23e]; Ps.-Luciano, <em>Asin.</em> 23; PGM 1, 24; Tb 2.1; 7.9 S; Jt 12.16; veja Anz 301s. —: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.7\" target=\"_blank\" rel=\"noopener noreferrer\">17.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.14\" target=\"_blank\" rel=\"noopener noreferrer\">22.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.12</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀ. εἰς τὸν ἔσχατον τόπον</span>, <strong>ocupar o lugar mais humilde</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.28</a> D = Agr 22 = ASyn nº 263, p. 353. <span class=\"greek\">ἀνέπεσαν πρασιαί</span>, <strong>tomaram seus lugares em grupos para comer</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.40</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.10</a>. <span class=\"greek\">ἀ. ἐπὶ τῆς γῆς</span>, <strong>tomar lugar no chão</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.6</a>; <span class=\"greek\">ἀ. ἐπὶ τὴν γῆν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15.35</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Inclinar-se enquanto reclinado à mesa, inclinar-se, recostar-se</strong> — Platão, <em>Phdr.</em> 254b e e; Políbio 1.21.2 —: <strong>recostou-se para trás de onde estava deitado</strong> — Goodsp. —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.25</a>, v.l. <span class=\"greek\">ἐπιπίπτω</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">21.20</a>. — M-M. TW.</p>\n</section></article><article id=\"entry-anaplasso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναπλάσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anaplássō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo médio <span class=\"greek\">ἀνεπλασάμην</span>; futuro passivo 2ª sg. <span class=\"greek\">ἀναπλασθήσῃ</span>, JosAs 15.4. Veja <span class=\"greek\">πλάσσω</span>; Heródoto e outros; PHal 1, 183 [séc. III a.C.]; Josefo, <em>C. Ap.</em> 2.248; Justino, <em>D.</em> 8.4, <span class=\"greek\">Χριστόν τινα</span>; Atanásio 27.1, <span class=\"greek\">εἴδωλα</span>, “formar imagens de culto”, e <em>R.</em> 13 p. 63, 15, “inventar, elaborar”; Melito, <em>P.</em> 47, 333; 83, 621, <span class=\"greek\">ἄνθρωπον</span>, “criar”. <strong>Formar de novo, formar, remodelar.</strong></p>\n<p class=\"entry-text\"><span class=\"sense-number\">a.</span> Literalmente, de um oleiro que remodela um vaso que estragou: <span class=\"greek\">πάλιν αὐτὸ ἀ.</span>, <strong>formá-lo novamente</strong>, 2 Cl 8.2; compare Wsd 15.7.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">b.</span> Figuradamente, da transformação espiritual de uma pessoa, B 6.11, 14. — Sv.</p>\n</section></article><article id=\"entry-anapleroo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναπληρόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anaplēróō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀναπληρώσω</span>; 1º aoristo <span class=\"greek\">ἀνεπλήρωσα</span>. Passivo: futuro 3ª pl. <span class=\"greek\">ἀναπληρωθήσονται</span>, Is 60.20; aoristo <span class=\"greek\">ἀνεπληρώθην</span>, LXX; perfeito 3ª pl. <span class=\"greek\">ἀναπεπλήρωνται</span>, Gn 15.16. Veja <span class=\"greek\">πληρόω</span>; Eurípides e posteriores.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Completar a quantidade de alguma coisa, tornar completo</strong>, figuradamente — Apiano, <em>Bell. Civ.</em> 3.47 §191, um corpo de tropas; 4.89 §374, obrigações pendentes; escólio a Nicandro, <em>Ther.</em> 447, <span class=\"greek\">τὴν ἡλικίαν</span> = período da infância; EpArist 75; Justino, <em>D.</em> 81.3, <span class=\"greek\">χίλια ἔτη</span>. <span class=\"greek\">ἀ. αὐτῶν τὰς ἁμαρτίας</span>, <strong>encher a medida de seus pecados</strong>, compare Gn 15.16, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2.16</a>; a menos que isto pertença à acepção 2 como metáfora comercial.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Executar um acordo ou uma obrigação, cumprir</strong>. De contrato: UPZ 112 V, 3 [203/202 a.C.]; O. Wilck. I 532–34. De dever: POxy 1121, 11. De uma ordem de trabalho: Josefo, <em>Ant.</em> 8.58. De profecias — 1 Esdr 1.54, <span class=\"greek\">εἰς ἀναπλήρωσιν τ. ῥήματος τ. κυρίου</span> —: <span class=\"greek\">ἀναπληροῦται αὐτοῖς ἡ προφητεία</span>, <strong>neles a profecia está sendo cumprida</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.14</a>. De reivindicações ou exigências impostas a alguém: <span class=\"greek\">ἀ. τὸν νόμον τ. Χριστοῦ</span>, <strong>cumprir a lei de Cristo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6.2</a>; <span class=\"greek\">ἀ. πᾶσαν ἐντολήν</span>, <strong>cumprir todo mandamento</strong>, B 21.8.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Suprir o que falta, preencher uma lacuna, substituir</strong> — Platão, <em>Symp.</em> 188e; SIG 364, 62; OGI 56, 46; PLille I, 8, 14 [séc. III a.C.]; Josefo, <em>Bell.</em> 4.198, <em>Ant.</em> 5.214. <span class=\"greek\">τὸ ὑστέρημα</span> — <em>Herm. Wr.</em> 13.1, <span class=\"greek\">τὰ ὑστερήματα ἀναπλήρωσον</span>; TestBenj 11.5 —, com genitivo de pessoa: <strong>compensar a ausência ou falta de alguém, representar alguém ausente</strong> — PMonac 14, 17s. [séc. VI d.C.], <span class=\"greek\">τῷ βικαρίῳ Ἑρμώνθεως ἀναπληροῦντι τὸν τόπον τοῦ τοποτηρητοῦ</span> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2.30</a>; 1 Cl 38.2. <span class=\"greek\">τὸν τ. ὑπακοῆς τόπον ἀναπληρῶσαι</span>, <strong>assumir a atitude de obediência</strong>, 1 Cl 63.1. <span class=\"greek\">τοὺς τύπους τῶν λίθων ἀ.</span>, <strong>preencher as impressões deixadas pelas pedras</strong>, compare EpArist 75, Hs 9, 10, 1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> <strong>Ocupar um lugar, ocupar, preencher.</strong> <span class=\"greek\">ὁ ἀναπληρῶν τ. τόπον τ. ἰδιώτου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14.16</a>. Por causa de <span class=\"greek\">ἰδιώτης</span> nos vv. 23s., a expressão não pode significar “aquele que ocupa a posição” — para esse sentido de <span class=\"greek\">τόπος</span>, veja o verbete 1e; para <span class=\"greek\">ἀναπληρόω</span> em conexão semelhante, Ps.-Clem., <em>Hom.</em> 3.60; compare o uso de <span class=\"greek\">ἀποπληρόω</span> em Epicteto 2.4.5; Josefo, <em>Bell.</em> 5.88 — de um <strong>“estranho”</strong>, isto é, em contraste com os que falam em línguas, alguém que não possui esse dom; PBachmann, com referência ao uso talmúdico; Ltzm., com referência a Whitaker; JSickenberger; H-DWendland.</p>\n<p class=\"entry-text\">Antes, <span class=\"greek\">ἀ. τὸν τόπον τινός</span> significa <strong>tomar ou preencher o lugar de alguém</strong> — compare Diodoro Sículo 19.22.2, <span class=\"greek\">τὸν τόπον ἀ.</span>; Herão de Alexandria I p. 8, 20, <span class=\"greek\">τὸν κενωθέντα τόπον ἀ.</span>; Platão, <em>Tim.</em> 79b, <span class=\"greek\">ἀ. τὴν ἕδραν</span> —, e <span class=\"greek\">τόπος</span> aqui significa um lugar realmente ocupado por um <span class=\"greek\">ἰδιώτης</span> na reunião, interpretação não compartilhada pela maioria dos tradutores ingleses; contudo, não é necessário supor que uma seção estivesse reservada aos catecúmenos, como fazem GHeinrici e JWeiss. Por outro lado, Ltzm. pergunta se cristãos batizados estariam melhor informados. Veja <span class=\"greek\">ἰδιώτης</span> 2 e GWhitaker, JTS 22, 1921, 268. — M-M. TW.</p>\n</section></article><article id=\"entry-anapneo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναπνέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anapnéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἀνέπνευσα</span>. Veja <span class=\"greek\">πνέω</span>; Homero e posteriores; também Jó 9.18; Fílon, Josefo. <strong>Respirar, recobrar o fôlego, reanimar-se</strong>: <span class=\"greek\">ἀνέπνευσεν ἡ ματρῶνα</span>, <strong>a mulher casada — Artemila — reanimou-se</strong>, de um desmaio, AcPl Ha 4, 2.</p>\n</section></article><article id=\"entry-anapologetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναπολόγητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anapológētos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀπολογέομαι</span>; Políbio 29.10.5; Dionísio de Halicarnasso 7.46; Plutarco, <em>Brut.</em> 1006 [46, 2]; Cícero, <em>Ad Att.</em> 16.7 e outros; Josefo, <em>C. Ap.</em> 2.137; Justino, <em>A I</em> 3.5; compare 28.3. <strong>Sem desculpa, indesculpável</strong> — Políbio 12.21.10; Dio Crisóstomo 2.39 —: <span class=\"greek\">εἰς τὸ εἶναι αὐτοὺς ἀναπολογήτους</span>, <strong>para que sejam indesculpáveis</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.20</a>; <span class=\"greek\">ἀ. εἶ</span>, <strong>és indesculpável</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2.1</a>.</p>\n</section></article><article id=\"entry-anaprasso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναπράσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anaprássō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">πράσσω</span>; Tucídides e outros; inscrições, papiros. Como termo comercial: <strong>exigir, cobrar</strong> um pagamento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19.23</a> v.l.</p>\n</section></article><article id=\"entry-anaptysso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναπτύσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anaptússō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro 3ª pl. <span class=\"greek\">ἀναπτύξουσι</span>, Dt 22.17; 1º aoristo <span class=\"greek\">ἀνέπτυξα</span>. <strong>Desenrolar</strong>, a respeito de um livro em forma de rolo — veja <span class=\"greek\">πτύσσω</span>; Heródoto e outros; Epicteto 1.17.21; Esopo, <em>Fab.</em> 332 H. = 264 P.; 4Rs 19.14; TestSol 22.6 P; TestAbr B 10 p. 115, 1 [Stone p. 78]; Josefo, <em>Vi.</em> 223; Irineu 1.10.3 [Harv. I 96, 9] —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.17</a>; PtK 4, p. 15, 30. — Renehan 1982, 24s.</p>\n</section></article><article id=\"entry-anapto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάπτω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anáptō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀνάψω</span>, LXX; 1º aoristo <span class=\"greek\">ἀνῆψα</span>, LXX. Passivo: futuro <span class=\"greek\">ἀναφθήσομαι</span>, LXX; aoristo passivo <span class=\"greek\">ἀνήφθην</span>. <strong>Acender, atear fogo</strong> — veja <span class=\"greek\">ἅπτω</span>; Eurípides, Heródoto e outros; PGiss 3, 8; PGM 13, 681; 2Cr 13.11; Justino.</p>\n<p class=\"entry-text\"><span class=\"greek\">ὕλην</span>, <strong>uma floresta</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3.5</a>; compare Polieno 4.7.9, <span class=\"greek\">πῦρ … ἀνῆψε τὴν ὕλην</span>; Fílon, <em>Aet. M.</em> 127; PsSol 12.2, <span class=\"greek\">πῦρ ἀνάπτον καλλονήν</span>; Atanásio 19.1, <span class=\"greek\">ἀνάψας πυράν</span>; Taciano 5.2. Compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.2</a> v.l.</p>\n<p class=\"entry-text\">A respeito de fogo — Eurípides, <em>Or.</em> 1137; TestAbr A 4 p. 80, 24 [Stone p. 8] = TestSol 6.10 L, <span class=\"greek\">λύχνους</span>; Josefo, <em>Ant.</em> 3.207 —: <span class=\"greek\">ἀνήφθη</span>, <strong>foi acendido, isto é, agora está ardendo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.49</a>; compare Diodoro Sículo 13.84.2, <span class=\"greek\">ὅταν ἀναφθῇ πῦρ</span>, “quando um fogo fosse aceso, ou estivesse ardendo”. Justino, <em>D.</em> 8.1: <span class=\"greek\">πῦρ ἐν τῇ ψυχῇ ἀνήφθη</span>. — M-M.</p>\n</section></article><article id=\"entry-anarithmetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναρίθμητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anaríthmētos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀριθμέω</span>; Píndaro, Heródoto e outros; LXX; JosAs 16.13 cód. A [p. 65, 1 Bat.]; Josefo, <em>Ant.</em> 17.214; Justino, Irineu. <strong>Inumerável, incontável</strong>, a respeito dos grãos de areia à beira-mar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.12</a>; compare Justino, <em>D.</em> 120.2, <span class=\"greek\">ἡ ἄμμος … ἀ.</span>. — DELG s.v. <span class=\"greek\">ἀριθμός</span>.</p>\n</section></article><article id=\"entry-anarpazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναρπάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anarpázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἀνήρπασα</span>; Homero e outros, em vários sentidos; Jz 9.25 A; EpArist 146; Josefo; Melito, <em>P.</em> 50, 358; 91, 683.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Levantar, erguer</strong>, GJs 6.1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Carregar para cima</strong>: <span class=\"greek\">ἐν τῷ ἁγιάσματι τοῦ κοιτῶνος</span>, <strong>na área consagrada do aposento</strong>, GJs 6.3.</p>\n</section></article><article id=\"entry-anaseio-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνασείω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anaseíō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Hesíodo e outros; PTebt 28, 20 [séc. II a.C.]; Josefo, <em>Bell.</em> 5.120. Literalmente, <strong>“sacudir”, “brandir”</strong>, por exemplo um escudo em Hesíodo, <em>Sc.</em> 344; sinônimo de <span class=\"greek\">σείω</span>. <strong>Fazer com que alguém ou algo seja perturbado; agitar, perturbar, transtornar, incitar</strong> — compare o coloquial “sacudir” —: Diodoro Sículo 13.91.4; 14.10.3; 17.62.5; 18.10.1; Is 36.18 Aq., Sym.</p>\n<p class=\"entry-text\">Com acusativo: <span class=\"greek\">τ. ὄχλον</span>, <strong>a multidão</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.11</a>; <span class=\"greek\">τ. λαόν</span>, <strong>o povo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.5</a>; compare Dionísio de Halicarnasso 8.81, <span class=\"greek\">τὸ πλῆθος</span>; Filodemo, <em>Rhet.</em> II 290 Sudh. <span class=\"greek\">τὴν Ἰκονείων πόλιν ἀνασείει, ἔτι δὲ καὶ τὴν σὴν Θέκλαν</span>, <strong>agita a cidade dos iconienses e também a tua Tecla</strong>, AcPl Ox 6, 20 = Aa I 242, 1. — M-M. TW.</p>\n</section></article><article id=\"entry-anaskapto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνασκάπτω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anaskáptō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Particípio perfeito passivo, neutro plural, <span class=\"greek\">ἀνεσκαμμένα</span>; Aristóteles, Teofrasto e outros; Sl 7.16; 79.17; Josefo. <strong>Escavar, arrasar, destruir</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.16</a> v.l.; veja <span class=\"greek\">κατασκάπτω</span>.</p>\n</section></article><article id=\"entry-anaskeuazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνασκευάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anaskeuázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">σκευάζω</span>, “preparar, aprontar”; Tucídides e outros, em vários sentidos; POxy 745, 5 [séc. I d.C.]; Josefo, <em>Bell.</em> 6.282, <em>Ant.</em> 14.406; 418; Irineu; Teófilo de Antioquia 3.4 [p. 212, 1]. Literalmente, <strong>“derrubar, desmontar”</strong> — processo de empacotar ou desmontar, em vez de aprontar —; depois, figuradamente, <strong>causar perturbação interior, transtornar, inquietar</strong>, com <span class=\"greek\">ταράσσειν</span>; compare Vétio Valente 212, 20, <span class=\"greek\">ἀνασκευασθήσεται καὶ ἐπιτάραχον γενήσεται</span>. <span class=\"greek\">ἀνασκευάζειν τὰς ψυχάς</span>, <strong>transtornar as almas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.24</a>. — M-M. TW.</p>\n</section></article><article id=\"entry-anaspa0-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνασπάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anaspáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀνασπάσω</span>; 1º aoristo <span class=\"greek\">ἀνέσπασα</span>; 1º aoristo passivo <span class=\"greek\">ἀνεσπάσθην</span>. Veja <span class=\"greek\">σπάομαι</span> [<span class=\"greek\">σπάω</span>]; Homero e outros; PTebt 420, 25; BGU 1041, 8; PGM 4, 2498; 2973; Hc 1.15; Dn 6.18; Bel 42 Theod.; TestSol 6.13 D; TestAbr A 11 p. 90, 4 [Stone p. 28]; ParJer 3.13; Josefo, <em>Ant.</em> 2.259 e outros. <strong>Puxar para cima, erguer</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.5</a>. A respeito do lençol que Pedro viu em sua visão: <span class=\"greek\">ἀνεσπάσθη εἰς τ. οὐρανόν</span>, <strong>foi erguido ao céu</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 11.10</a>; compare Ferecrates Com., Fgm. 180 K., <span class=\"greek\">κάδους ἀνασπῶν</span>. — M-M.</p>\n</section></article><article id=\"entry-anasta-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάστα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anásta⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνίστημι</span>.</p>\n</section></article><article id=\"entry-anastasis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάστασις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anástasis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνίστημι</span>; Ésquilo, Heródoto e posteriores, em vários sentidos.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Mudança para melhor na condição, levantamento, elevação</strong> — Lm 3.63; Zc 3.8; Josefo, <em>Ant.</em> 17.212; 18.301, aqui a respeito da “ereção” de uma estátua. <span class=\"greek\">κεῖται εἰς πτῶσιν καὶ ἀ. πολλῶν</span>, <strong>está destinado à queda e ao levantamento de muitos</strong>, a respeito de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.34</a>; isto é, por causa dele muitos cairão e outros se levantarão, a saber, em relação a Deus. Para o contraste com <span class=\"greek\">πτῶσις</span>, compare Evágrio Pôntico, <em>Sent.</em> 5.19 p. 327 Frankenberg: <span class=\"greek\">ἡ μικρὰ τ. σώματος ἀνάστασίς ἐστιν ἡ μετάθεσις αὐτοῦ ἐκ πτώσεως τ. ἀσελγείας εἰς τὴν τ. ἁγιασμοῦ ἀνάστασιν</span>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Especialmente, <strong>ressurreição dentre os mortos, ressurreição</strong> — Ésquilo, <em>Eum.</em> 648, <span class=\"greek\">ἅπαξ θανόντος οὔτις ἐστ’ ἀ.</span>; compare Jó 7.9s.; 16.22; Ps.-Luciano, <em>De Salt.</em> 45; Élio Aristides 32.25 K. = 12 p. 142 D.; 46 p. 300 D.; IGR IV 743, 25, <span class=\"greek\">[ο]ἱ δὴ δ[είλ]αιοι πάντ[ες] εἰς ἀ[νά]στασιν|[—-]</span> — a pedra se interrompe depois de <span class=\"greek\">ἀ.</span>, e alguns entendem que se deve suprir <span class=\"greek\">βλέποντες</span> ou semelhante —; 2 Macc 7.14; 12.43.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2a.</span> No passado: a respeito da <strong>ressurreição de Jesus</strong> — Orígenes, <em>C. Cels.</em> 5.57.25 —: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">2.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">4.33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3.10</a> — JFitzmyer, BRigaux Festschr., 1970, 411–25 —; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3.21</a>; 1 Cl 42.3; ISm 3.1, 3. Mais especificamente, <span class=\"greek\">ἀ. ἐκ νεκρῶν</span>, <strong>ressurreição dentre os mortos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1.3</a>; <span class=\"greek\">ἀ. νεκρῶν</span>, <strong>ressurreição dos mortos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.4</a>; com a paixão de Jesus, IEph 20.1; Mg 11; Tr ins.; Phld ins.; 8.2; 9.2; Sm 7.2; 12.2; compare 1.2.</p>\n<p class=\"entry-text\"><span class=\"greek\">τὸν Ἰησοῦν καὶ τὴν ἀ. εὐαγγελίζεσθαι</span>, <strong>proclamar Jesus e a ressurreição</strong>, isto é, sua ressurreição e, em consequência, a possibilidade de uma ressurreição geral, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.18</a>; mas veja a acepção 3 abaixo. <span class=\"greek\">τὸν Ἰησοῦν καὶ τὴν ἀνάστασιν</span> também poderia significar <strong>“a ressurreição de Jesus”</strong>, como talvez em Nicolau de Damasco, 90 Fgm. 130, 18 p. 400, 17 Jac., <span class=\"greek\">μνήμη τἀνδρὸς καὶ φιλοστοργίας</span> = “a memória do homem e de seu afeto”; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.32\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.32</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">4.2</a>.</p>\n<p class=\"entry-text\">A respeito das ressurreições realizadas por Elias e Eliseu: <span class=\"greek\">ἔλαβον γυναῖκες ἐξ ἀ. τοὺς νεκροὺς αὐτῶν</span>, <strong>mulheres receberam seus mortos por ressurreição</strong> — isto é, a viúva de Sarepta e a sunamita, 3Rs 17.23; 4Rs 4.36 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.35\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.35</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2b.</span> Da <strong>ressurreição futura</strong> — Teófilo de Antioquia 1.13 [p. 86, 25] —, ligada ao Dia do Juízo. É descrita como <span class=\"greek\">ἀ. νεκρῶν</span>, <strong>ressurreição dos mortos</strong> — Dídimo, <em>Gen.</em> 96, 13 —: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.15\" target=\"_blank\" rel=\"noopener noreferrer\">24.15</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.23\" target=\"_blank\" rel=\"noopener noreferrer\">26.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15.12s.</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">21</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.42\" target=\"_blank\" rel=\"noopener noreferrer\">42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6.2</a>; D 16.6. Ou <span class=\"greek\">ἀ. ἐκ νεκρῶν</span>, <strong>ressurreição dentre os mortos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20.35</a>; B 5.6; AcPlCor 2.35; compare Ar. 15.3; Justino, <em>D.</em> 45.2; compare IPol 7.1; Pol 7.1; MPol 14.2.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀ. σαρκός</span>, <strong>ressurreição da carne</strong>, não ocorre no NT; AcPlCor 1.12; 2.24; Justino, <em>D.</em> 80.5; <span class=\"greek\">σωμάτων</span>, Taciano 6.1; Atanásio, <em>R.</em> 11 p. 59, 14. A respeito de Jesus: <span class=\"greek\">τὴν ἀ. ποιεῖν</span>, <strong>produzir a ressurreição dos mortos</strong>, B 5.7. A paixão de Jesus como nossa ressurreição, ISm 5.3. <span class=\"greek\">ἀθάνατος τῆς ἀ. καρπός</span>, <strong>fruto imortal da ressurreição</strong>, 2 Cl 19.3. Descrita como <span class=\"greek\">ἀ. κρείττων</span>, <strong>ressurreição melhor</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.35\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.35</a>, em contraste com a ressurreição do passado, porque esta, afinal, foi seguida pela morte. <span class=\"greek\">ἡ μέλλουσα ἀ.</span>, <strong>a ressurreição futura</strong> — Teófilo de Antioquia 2.15 [p. 138, 17] —, 1 Cl 24.1. <span class=\"greek\">ἡ κατὰ καιρὸν γινομένη ἀ.</span>, <strong>a ressurreição que ocorre em intervalos regulares</strong> — isto é, estações, dia e noite —, como tipo da ressurreição futura, 1 Cl 24.2.</p>\n<p class=\"entry-text\">Mais detalhes em João, que menciona uma <span class=\"greek\">ἀ. ἐν τῇ ἐσχάτῃ ἡμέρᾳ</span>, <strong>ressurreição no último dia</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.24</a>, e distingue entre <span class=\"greek\">ἀ. κρίσεως</span>, <strong>ressurreição para julgamento</strong>, para os maus, e <span class=\"greek\">ἀ. ζωῆς</span>, <strong>ressurreição para a vida</strong>, para os que praticam o bem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">5.29</a>. Cristo chama a si mesmo <span class=\"greek\">ἡ ἀ.</span> e <span class=\"greek\">ἡ ζωή</span>, <strong>a ressurreição e a vida</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">11.25</a>, pois medeia ambas aos seres humanos.</p>\n<p class=\"entry-text\">Paulo procura demonstrar a validade da crença na ressurreição de Jesus em termos da ressurreição dos mortos em geral, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15.12ss.</a>; veja MDahl, <em>The Resurrection of the Body: A Study of 1 Cor 15</em>, 1962, e veja <span class=\"greek\">τάγμα</span> 1b. <span class=\"greek\">γνῶναι … τὴν δύναμιν τῆς ἀ. αὐτοῦ</span>, <strong>conhecer … o poder de sua ressurreição</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3.10</a>.</p>\n<p class=\"entry-text\"><a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.14</a> menciona somente uma <strong>ressurreição dos justos</strong>, como em algumas concepções intertestamentárias; igualmente B 21.1. Hebraísmo: <span class=\"greek\">υἱοὶ τῆς ἀ.</span>, com <span class=\"greek\">υἱοὶ θεοῦ</span>, <strong>filhos da ressurreição</strong> = participantes da ressurreição, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20.36</a>. Uma segunda ressurreição é pressuposta pela expressão <span class=\"greek\">ἀ. ἡ πρώτη</span>, <strong>a primeira ressurreição</strong>, de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20.5s.</a>.</p>\n<p class=\"entry-text\">Negação da ressurreição pelos saduceus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22.23</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.28\" target=\"_blank\" rel=\"noopener noreferrer\">28</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">30s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.18</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20.27</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.33\" target=\"_blank\" rel=\"noopener noreferrer\">33</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.35\" target=\"_blank\" rel=\"noopener noreferrer\">35s.</a>; sobre isso, veja Schürer II 391; 411. Pelos epicureus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.18</a> — ERohde, <em>Psyche</em>³, 1903, II 331–35; compare a inscrição mencionada acima no início da acepção 2. E por cristãos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15.12</a>, provavelmente no sentido de Justino, <em>D.</em> 80.4: <span class=\"greek\">λέγουσι μὴ εἶναι νεκρῶν ἀνάστασιν, ἀλλ’ ἅμα τῷ ἀποθνῄσκειν τὰς ψυχὰς αὐτῶν ἀναλαμβάνεσθαι εἰς τ. οὐρανόν</span>, <strong>“dizem que não há ressurreição dos mortos, mas que, no momento da morte, suas almas são levadas ao céu”</strong>; veja JWilson, ZNW 59, 1968, 90–107.</p>\n<p class=\"entry-text\"><a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2.18</a>; compare Menandro em Irineu 1.23.5 [Harv. I 195], <em>resurrectionem enim per id quod est in eum baptisma, accipere eius discipulos, et ultra non posse mori, sed perseverare non senescentes et immortales</em>: <strong>“[Menandro ensina que] seus seguidores recebem a ressurreição por serem batizados nele e, depois disso, já não podem morrer, mas permanecem sem envelhecer e imortais”</strong>; compare Justino, <em>A I</em> 26.4; Valentino em Clemente de Alexandria, <em>Str.</em> 4.13.91; Tertuliano, <em>Carn. Resurr.</em> 25, <em>agnitio sacramenti</em> = <span class=\"greek\">ἡ τοῦ μυστηρίου γνῶσις</span>, <em>resurrectio</em>.</p>\n<p class=\"entry-text\">Bibliografia geral sobre a crença na ressurreição: FNötscher, <em>Altoriental. u. atl. Auferstehungsglaube</em>, 1926; JLeipoldt, <em>Sterbende u. auferstehende Götter</em>, 1923; Cumont³, 1931; ANikolainen, <em>D. Auferstehungsglauben in d. Bibel u. in ihrer Umwelt</em>, I <em>Relgesch. Teil</em>, 1944; II <em>NT</em>, 1946; WBousset, <em>Rel.</em>³, 1926, 269–74 e outros; Billerb. IV, 1928, 1166–98.</p>\n<p class=\"entry-text\">Sobre a ressurreição de Cristo: AMeyer, <em>D. Auferstehung Christi</em>, 1905; KLake, <em>The Historical Evidence of Res. of Jesus Christ</em>, 1907; LBrun, <em>D. Auferst. Christi in d. urchr. Überl.</em>, 1925; PGardner-Smith, <em>The Narratives of the Resurrection</em>, 1926; SMcCasland, <em>The Res. of Jesus</em>, 1932; MGoguel, <em>La foi à la résurr. de Jésus dans le Christianisme primitif</em>, 1933; EFascher, ZNW 26, 1927, 1–26; EFuchs, ZKG 51, 1932, 1–20; AThomson, <em>Did Jesus Rise from the Dead?</em>, 1940; EHirsch, <em>D. Auferstehungsgeschichten u. d. chr. Glaube</em>, 1940; PAlthaus, <em>D. Wahrheit des kirchl. Osterglaubens</em>², 1941; WMichaelis, <em>D. Erscheinungen des Auferstandenen</em>, 1944; ARamsey, <em>The Res. of Christ</em>, 1945; JLeipoldt, <em>Zu den Auferstehungsgeschichten</em>: TLZ 73, 1948, 737–42; KRengstorf, <em>Die Auferstehung Jesu</em>², 1954; GKoch, <em>Die Auferstehung J. Christi</em>, 1959; HGrass, <em>Ostergeschehen u. Osterberichte</em>, 1956; ELohse, <em>Die Auferstehung J. Chr. im Zeugnis des Lk</em>, 1961; HvCampenhausen, <em>Tradition and Life in the Early Church</em>, 1968, 42–89; WCraig, <em>Assessing the NT Evidence for the Historicity of the Resurrection of Jesus</em>, 1989; GLüdemann, <em>Die Auferstehung Jesu</em>, 1994. Veja também <span class=\"greek\">τάφος</span> 1.</p>\n<p class=\"entry-text\">Sobre a ressurreição em Paulo: KDeissner, <em>Auferstehungshoffnung u. Pneumagedanke b. Pls</em>, 1912; GVos, <em>The Pauline Doctrine of the Res.</em>: PTR 27, 1929, 1–35; 193–226; FGuntermann, <em>D. Eschatologie d. hl. Pls</em>, 1932; HMolitor, <em>Die Auferstehung d. Christen und Nichtchristen nach d. Ap. Pls</em>, 1933; LSimeone, <em>Resurrectionis iustorum doctr. in Ep. S. Pauli</em>, 1938; DStanley, <em>Christ’s Resurrection in Pauline Soteriology</em>, 1961; CMoule, NTS 12, 1965/66, 106–23; MdeBoer, <em>The Defeat of Death</em>, 1988; JHolleman, <em>A Traditio-Historical Study of Paul’s Eschatology in 1 Cor 15</em> (NovT Suppl. 84), 1996.</p>\n<p class=\"entry-text\">RGrant, <em>Miracle and Nat. Law</em>, 1952, 221–63; JBuitkamp, <em>Auferstehungsglaube in den Qumrantexten</em>, diss. Groningen, 1964; GWild, <em>Auferstehungsglaube des späten Israel</em>, diss. Bonn, 1967; W. Pannenberg, <em>Grundzüge der Christologie</em>⁶, 1982, 74ss.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Uma divindade dentro de um sistema politeísta, Ressurreição</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.18</a>. Essa interpretação, apresentada primeiro por Crisóstomo — <em>Hom. in Act.</em> 38.1 —, encontrou defensores modernos; veja Haenchen ad loc. A questão semântica surge do fato de a narrativa apresentar os ouvintes como teologicamente ignorantes. A suposição deles é que Paulo parecia ser proclamador de <strong>“novas divindades”</strong>, v. 18a. Da perspectiva deles, o termo <span class=\"greek\">ἀ.</span> sugere uma divindade chamada <strong>Ressurreição</strong>; abstrações identificadas como divindades não eram incomuns no mundo greco-romano, veja EA 19, 1992, 71–73. Mas o autor onisciente informa ao leitor que o sentido pretendido é a ressurreição corporal, como na acepção 2 acima. — DELG s.v. <span class=\"greek\">ἵστημι</span>. M-M. TW. Sv.</p>\n</section></article><article id=\"entry-anastatoo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναστατόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anastatóō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro 3ª sg. <span class=\"greek\">ἀναστατῶσει</span>, Dn 7.23; 1º aoristo <span class=\"greek\">ἀνεστάτωσα</span>. Grego tardio: papiros, por exemplo BGU 1858, 12 [séc. I a.C.]; POxy 119, 10; PGM 4, 2244; LXX; Áquila e Símaco; veja Nägeli 47s. <strong>Perturbar a estabilidade de uma pessoa ou grupo, perturbar, transtornar, desestabilizar</strong>: <span class=\"greek\">τὴν οἰκουμένην</span>, <strong>o mundo habitado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.6</a>. Dos líderes de um partido que perturbam a igreja, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5.12</a>; compare BGU 1079, 20 [41 d.C.], <span class=\"greek\">μὴ ἵνα ἀναστατώσῃς ἡμᾶς</span>. Absolutamente: <span class=\"greek\">ὁ ἀναστατώσας</span>, <strong>o homem que levantou uma revolta</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.38</a>. — DELG s.v. <span class=\"greek\">ἵστημι</span>. M-M.</p>\n</section></article><article id=\"entry-anastauroo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνασταυρόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anastauróō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">σταυρόω</span>; Heródoto e outros. Sempre, simplesmente, <strong>crucificar</strong>, com <span class=\"greek\">ἀνά</span> = “para cima”; compare Platão, <em>Gorg.</em> 473c; <em>Hellen. Oxy.</em> XV, 5; Políbio 1.11.5; 1.24.6; Diodoro Sículo 2.1.10; 2.44.2; 13.111.5; 14.53.5; Plutarco, <em>Fab.</em> 177 [6, 5], <em>Cleom.</em> 823 [39, 2]; Cáriton 4.2.6; Esopo, <em>Fab.</em> 152 P. [= <span class=\"greek\">σταυρόω</span> 264 H.]; POxy 842, col. 18, 22; Josefo, <em>Bell.</em> 2.306; 5.449, <em>Ant.</em> 2.73; 11.246, <em>Vi.</em> 420.</p>\n<p class=\"entry-text\">Assim, <span class=\"greek\">ἀνασταυροῦντας ἑαυτοῖς τὸν υἱὸν τ. θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6.6</a>, pode significar <strong>“visto que, para seu próprio dano, crucificam o Filho de Deus”</strong>, a respeito de cristãos apóstatas; mas o contexto parece exigir o sentido figurado <strong>“crucificar novamente”</strong>, com <span class=\"greek\">ἀνά</span> = “de novo”, e assim o entenderam os antigos tradutores e os Pais gregos. Compare L-S-J-M s.v. e Lampe s.v. 2. — A. Vitti, Verb. Dom. 22, 1942, 174–82. — TW.</p>\n</section></article><article id=\"entry-anastenazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναστενάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anastenázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἀνεστέναξα</span>. Veja <span class=\"greek\">στενάζω</span>; Ésquilo, <em>Choëph.</em> 335; Heródoto 1.86.3; PGM 4, 2492s.; Sir 25.18; Lm 1.4; Sus 22 Teod.; JosAs; ApcMos 9. <strong>Suspirar profundamente</strong>: <span class=\"greek\">ἀναστενάξας τῷ πνεύματι αὐτοῦ λέγει</span>, <strong>suspirou profundamente em seu espírito — isto é, consigo mesmo; compare Mc 2.8 — e disse</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.12</a>; compare 2 Macc 6.30; J. Gibson, BT 38, 1987, 122–25.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀνεστενάζων ὅτι ἐθριαμβεύετο ὑπὸ τῆς πόλεως</span>, <strong>afligido por estar sujeito ao ridículo da cidade, como se estivesse sendo exibido numa procissão triunfal</strong>, AcPl Ha 4, 12s.; para aflição em situação aparentemente sem esperança, compare <em>Il.</em> 10.9 e outros. Em GJs 3.1; 12.2, erro por <span class=\"greek\">ἀτενίζω</span> ou <span class=\"greek\">ἐνατενίζω</span>; veja de Strycker p. 298 e também a sequência <span class=\"greek\">ἀνεστέναξε καὶ ἦν ἀτενίζουσα</span> em JosAs 8.8. — C. Bonner, HTR 20, 1927, 171–81. — DELG s.v. <span class=\"greek\">στένω</span>.</p>\n</section></article><article id=\"entry-anastethi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάστηθι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anástēthi⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνίστημι</span>.</p>\n</section></article><article id=\"entry-anastrepho-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναστρέφω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anastréphō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀναστρέψω</span>, LXX; 1º aoristo <span class=\"greek\">ἀνέστρεψα</span>. Passivo: futuro 3ª sg. <span class=\"greek\">ἀναστραφήσεται</span>, Sir 39.3; 50.28; 2º aoristo <span class=\"greek\">ἀνεστράφην</span>, particípio <span class=\"greek\">ἀναστραφείς</span>; perfeito 3ª sg. <span class=\"greek\">ἀνέστραπται</span>, Js 5.6. Veja <span class=\"greek\">στρέφω</span>; Homero e posteriores, em vários sentidos; inscrições, papiros, LXX; TestSol 18.12; TestAsh 6.3; Fílon, Josefo; Justino, <em>A I</em> 53.3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Transitivo: <strong>virar completamente, derrubar, transtornar</strong> — Políbio 5.9.3; Ps.-Apolodoro 3.8.1; Dionísio de Halicarnasso 9.6.2, todos segundo os manuscritos. <span class=\"greek\">τὰς τραπέζας</span>, <strong>virar as mesas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2.15</a> v.l. por <span class=\"greek\">ἀνατρέπω</span>; veja o comentário no local.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Passar tempo numa localidade, permanecer, viver</strong>; passivo com sentido ativo, com <span class=\"greek\">ἐν</span> — Platão, <em>Rep.</em> 8.558a, <span class=\"greek\">μένειν καὶ ἀ. ἐν</span>; Xenofonte, <em>Hell.</em> 6.4.16; Políbio 3.33.18; Epicteto 1.2.26; Plutarco, <em>Fab.</em> 179 [9, 5]; Js 5.6; Ez 19.6; compare P. Katz, JTS 47, 1946, 31 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17.22</a> v.l.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Conduzir-se segundo certos princípios, agir, comportar-se, conduzir-se, viver</strong>; passivo com sentido ativo, porém não literal, extensão da acepção 2 — literalmente, “voltar-se para cá e para lá”. Xenofonte e outros; Políbio 1.9.7; 1.74.13 e outros; Chion, <em>Ep.</em> 7.1; Crates, <em>Ep.</em> 35.2 p. 216 H.; Vett. Val., índice; inscrições, papiros; Dssm. B 83, NB 22 [BS 88; 194], LO 264s. [LAE 315]; Nägeli 38; Thieme 14; Hatch 136; Pr 20.7; Ez 22.30; Josefo, <em>Ant.</em> 15.190; Justino, <em>A I</em> 53.3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3a.</span> Com advérbio: <span class=\"greek\">ἁγνῶς</span>, <strong>puramente</strong>, Hs 9, 27, 2; <span class=\"greek\">ἱσχυρῶς καὶ ἀνδρείως ἀ.</span>, <strong>conduzir-se com força e coragem</strong>, Hs 5, 6, 6; <span class=\"greek\">καλῶς ἀ.</span>, <strong>conduzir-se bem</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13.18</a>; <span class=\"greek\">ἀμέμπτως</span>, <strong>irrepreensivelmente</strong>, 1 Cl 63.3; <span class=\"greek\">ἀ. … ὁσίως καὶ δικαίως</span>, <strong>conduzir-se santa e justamente</strong>, 2 Cl 5.6.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3b.</span> Por locuções prepositivas: <span class=\"greek\">ἐν ταῖς ἐπιθυμίαις τῆς σαρκός</span>, <strong>viver nas paixões da carne, isto é, ser escravo da paixão física</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2.3</a>; <span class=\"greek\">ἐν παλαιοῖς πράγμασιν</span>, <strong>segundo os antigos costumes — isto é, israelitas</strong>, IMg 9.1; <span class=\"greek\">ἐν τρυφαῖς πολλαῖς</span>, Hm 11.12; <span class=\"greek\">ἐν πλάνῃ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2.18</a>; <span class=\"greek\">ἀ. ἐν οἴκῳ θεοῦ</span>, <strong>conduzir-se na casa de Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 3.15</a>; <span class=\"greek\">ἐν φόβῳ ἀ.</span>, <strong>viver em temor</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1.17</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3c.</span> Com advérbio e locução prepositiva: <span class=\"greek\">ὁσίως ἀ. ἐν καθαρᾷ διανοίᾳ</span>, <strong>viver santamente com mente pura</strong>, 1 Cl 21.8.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3d.</span> Com mais de um <span class=\"greek\">ἐν</span> em sentidos diversos: <span class=\"greek\">ἐν ἁπλότητι … τοῦ θεοῦ, καὶ οὐκ ἐν σοφίᾳ σαρκικῇ ἀλλ’ ἐν χάριτι θεοῦ ἀνεστράφημεν ἐν τῷ κόσμῳ</span>, <strong>conduzimo-nos no mundo em sinceridade diante de Deus, não com sabedoria terrena, mas na graça de Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1.12</a>. De modo algo semelhante a <span class=\"greek\">ἀ. ἐν τῷ κόσμῳ</span>, <span class=\"greek\">οὕτως ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.33</a>, significa <strong>viver de tal maneira</strong> — em meio a opróbrio e aflição —, isto é, <strong>ser tratado de tal maneira</strong>, e não praticar ativamente alguma coisa.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> <strong>Estar envolvido com alguém em estreita proximidade, associar-se</strong>, intransitivo, <span class=\"greek\">μετά τινος</span>, <strong>com alguém</strong> — Josefo, <em>Ant.</em> 1.55, com <span class=\"greek\">μετά</span>; diferente de <span class=\"greek\">πρός τινος</span> em Epicteto 4.1.116, onde a ênfase recai no encontro pessoal face a face e nas relações com outro —, B 19.6; D 3.9.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">5.</span> Intransitivo: <strong>voltar a uma localidade, retornar, voltar</strong> — Apiano, <em>Bell. Civ.</em> 5.51 §215; Polieno 1.48.1; 8.12; Crates, <em>Ep.</em> 28.8 [Malherbe p. 78]; Sus 49 Teod.; Jt 15.7; 1 Macc 5.8; 10.52, 55 v.l.; Josefo, <em>Ant.</em> 7.226 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 5.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">15.16</a>. — M-M. TW.</p>\n</section></article><article id=\"entry-anastrophe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναστροφή</h1><div class=\"entry-meta\"><span class=\"greek\">ῆς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anastrophḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Em vários sentidos desde Ésquilo, pré-socráticos e outros; inscrições, papiros, LXX; Josefo, <em>Ant.</em> 18.359 e outros; Justino, <em>A I</em> 10.2. <strong>Conduta expressa segundo determinados princípios, modo de vida, conduta, comportamento</strong> — Políbio 4.82.1 [F. Kälker, <em>Quaest. de elocut. Polyb.</em> = <em>Leipz. Stud.</em> III/2, 1880, 301]; Teles p. 41, 2; Diógenes Laércio; Epicteto 1.9.24; 1.22.13; inscrições: índice de SIG; IG XII/1, 1032, 6 [séc. II a.C.]; IMagnMai 91b, 6; IPergamon 86; PTebt 703, 270 [séc. III a.C.]; Tb 4.14; 2 Macc 6.23; EpArist 130; 216.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἠκούσατε τ. ἐμὴν ἀ. ποτε ἐν τῷ Ἰουδαϊσμῷ</span>, <strong>ouvistes de minha conduta quando eu ainda estava no judaísmo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.13</a>. <span class=\"greek\">κατὰ τὴν προτέραν ἀ.</span>, <strong>segundo vosso antigo — isto é, pré-cristão — modo de vida</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.22</a>; compare GDI 4320, 5s., <span class=\"greek\">κατὰ τὰν ἄλλαν ἀναστροφάν</span> [Rodes]. <span class=\"greek\">ἡ ἐν φόβῳ ἁγνὴ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3.2</a>; compare v. 1. <span class=\"greek\">ἡ ἀγαθὴ ἐν Χριστῷ ἀ.</span>, v. 16. <span class=\"greek\">ἡ καλὴ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2.12</a>. <span class=\"greek\">ἡ ματαία ἀ. πατροπαράδοτος</span>, <strong>o fútil — isto é, dirigido a fins fúteis — modo de vida transmitido por vossos pais</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1.18</a>. <span class=\"greek\">ἡ ἐν ἀσελγείᾳ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2.7</a>. <span class=\"greek\">ἡ ἔκβασις τῆς ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13.7</a>. <span class=\"greek\">ἅγιον ἐν πάσῃ ἀ. γίνεσθαι</span>, <strong>ser santo em toda a vossa conduta</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1.15</a>. Com <span class=\"greek\">λόγος, ἀγάπη</span> etc., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 4.12</a>. Plural: <span class=\"greek\">ἅγιαι ἀ. καὶ εὐσέβειαι</span>, <strong>condutas santas e atos de piedade</strong> — plural para incluir todas as variedades; compare EpArist 130 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3.11</a>. — D. Daube, <em>Alexandrian Methods of Interpretation and the Rabbis</em>, Festschrift H. Lewald, 1953, 27–44. — DELG s.v. <span class=\"greek\">στρέφω</span>. M-M. TW. Spicq.</p>\n</section></article><article id=\"entry-anasozo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνασῴζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anasṓzō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Passivo: futuro 3ª pl. <span class=\"greek\">ἀνασωθήσονται</span>, Ez 7.16; particípio aoristo <span class=\"greek\">ἀνασωθείς</span>, LXX; particípio perfeito <span class=\"greek\">ἀνασεσῳσμένος</span>, LXX. Veja <span class=\"greek\">σῴζω</span>; Sófocles, Heródoto e outros; Hipócrates, <em>Ep.</em> 11.3 H., <span class=\"greek\">ἀνασῴζω τι</span>; OGI 493, 21; UPZ 19, 12; PTebt 920, 24 [ambos séc. II a.C.]; Jr 27.29; Zc 2.11; Josefo, <em>Ant.</em> 5.214; 6.364; 365. <strong>Resgatar, salvar</strong>. No passivo: <span class=\"greek\">τοὺς ἀνασῳζομένους</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.14</a> P46, em lugar de <span class=\"greek\">τοὺς ἁγιαζομένους</span>. — New Docs 4, 142, nº 41. DELG s.v. <span class=\"greek\">σῶς</span>. TW.</p>\n</section></article><article id=\"entry-anatassomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνατάσσομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anatássomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἀνεταξάμην</span>. Literalmente, <strong>“dispor em ordem apropriada”</strong>; figuradamente, <strong>organizar numa série</strong>. Veja <span class=\"greek\">τάσσω</span>; Plutarco, <em>Mor.</em> 968c; Irineu 3.21.2 [Harv. II 114, 12]. <span class=\"greek\">διήγησιν ἀ.</span>, <strong>redigir, compor ou compilar uma narrativa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.1</a>, implicando o uso de material tradicional e, como o contexto indica, com ênfase na sequência ordenada.</p>\n<p class=\"entry-text\">Sinônimo: <span class=\"greek\">συντάσσεσθαι</span>, <strong>compilar</strong>. Compare as versões siríaca, copta e gótica; a 39ª Carta Festal de Atanásio em E. Preuschen, <em>Analecta</em>² II, 1910, p. 43, 9; também <em>Hippiatr.</em> 1.1, num prólogo que recorda Lc 1.1; EpArist 144. Compare P. Corssen, GGA 1899, 317s.; Zahn sobre Lc 1.1; P. Scheller, <em>De hellenist. conscribendae historiae arte</em>, diss. Leipzig, 1911, 23; J. Mansion, <em>Serta Leodiensia</em>, 1930, 261–67; H. Cadbury, JBL 52, 1933, 56–58; L. Alexander, <em>The Preface to Luke’s Gospel</em>, 1993, 110s. Veja também <span class=\"greek\">παρακολουθέω</span> 4. — M-M. TW.</p>\n</section></article><article id=\"entry-anatethrammenos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνατεθραμμένος</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anatethramménos⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀνατρέφω</span>.</p>\n</section></article>"};
